  (bv_unsigned a + off + Z.of_nat (length bs) <= 2 ^ 64)%Z ->
  (forall i, (0 <= i < Z.of_nat (length bs))%Z ->
     mem (Z_to_bv 64 (bv_unsigned a + off + i)) = Some (nth (Z.to_nat i) bs (Z_to_bv 8 0))) ->
